WITH observations AS (
SELECT time_bucket('5 seconds', recorded_timestamp) AS time, metric_name,  100 * MAX(metric_max(value)) AS value, service_name, service_namespace, deployment_environment, service_instance_id, attributes FROM metrics WHERE otel_resource_attributes->>'logfire.metric_schema.version'='1' AND ($session = 'all' OR otel_resource_attributes->>'session_id' = $session) AND ($build = '' OR otel_resource_attributes->>'build.id' = $build) AND metric_name IN ('app.main_thread.cpu.utilization','app.process.cpu.utilization') GROUP BY time_bucket('5 seconds', recorded_timestamp), metric_name, service_name, service_namespace, deployment_environment, service_instance_id, attributes 
) SELECT time, concat(CASE metric_name WHEN 'app.main_thread.cpu.utilization' THEN 'Main thread' WHEN 'app.process.cpu.utilization' THEN 'Process' WHEN 'app.main_queue.delay' THEN 'Completed delay' WHEN 'app.main_queue.pending_age.max' THEN 'Pending age' WHEN 'game.frame.interval' THEN 'Callback interval' WHEN 'game.renderer.preparation' THEN 'Preparation' WHEN 'game.gpu.commands.duration' THEN 'GPU commands' WHEN 'game.display.present.interval' THEN 'Presentation interval' WHEN 'game.display.present.lateness' THEN 'Presentation lateness' ELSE metric_name END, ' · source ', CAST(dense_rank() OVER (ORDER BY service_name, service_namespace, deployment_environment, service_instance_id, CAST(attributes AS TEXT)) AS TEXT)) AS series, value FROM observations ORDER BY time DESC LIMIT 10000

WITH observations AS (
SELECT time_bucket('5 seconds', recorded_timestamp) AS time, metric_name,  MAX(metric_max(value)) AS value, service_name, service_namespace, deployment_environment, service_instance_id, attributes FROM metrics WHERE otel_resource_attributes->>'logfire.metric_schema.version'='1' AND ($session = 'all' OR otel_resource_attributes->>'session_id' = $session) AND ($build = '' OR otel_resource_attributes->>'build.id' = $build) AND metric_name IN ('app.main_queue.delay','app.main_queue.pending_age.max') GROUP BY time_bucket('5 seconds', recorded_timestamp), metric_name, service_name, service_namespace, deployment_environment, service_instance_id, attributes 
) SELECT time, concat(CASE metric_name WHEN 'app.main_thread.cpu.utilization' THEN 'Main thread' WHEN 'app.process.cpu.utilization' THEN 'Process' WHEN 'app.main_queue.delay' THEN 'Completed delay' WHEN 'app.main_queue.pending_age.max' THEN 'Pending age' WHEN 'game.frame.interval' THEN 'Callback interval' WHEN 'game.renderer.preparation' THEN 'Preparation' WHEN 'game.gpu.commands.duration' THEN 'GPU commands' WHEN 'game.display.present.interval' THEN 'Presentation interval' WHEN 'game.display.present.lateness' THEN 'Presentation lateness' ELSE metric_name END, ' · source ', CAST(dense_rank() OVER (ORDER BY service_name, service_namespace, deployment_environment, service_instance_id, CAST(attributes AS TEXT)) AS TEXT)) AS series, value FROM observations ORDER BY time DESC LIMIT 10000

WITH observations AS (
SELECT time_bucket('5 seconds', recorded_timestamp) AS time,  100 * SUM(CASE WHEN metric_name='game.frame.over_25ms.count' THEN metric_sum(value) ELSE 0 END) / NULLIF(SUM(CASE WHEN metric_name='game.frame.count' THEN metric_sum(value) ELSE 0 END), 0) AS value, service_name, service_namespace, deployment_environment, service_instance_id, attributes FROM metrics WHERE otel_resource_attributes->>'logfire.metric_schema.version'='1' AND aggregation_temporality='delta' AND metric_name IN ('game.frame.count','game.frame.over_25ms.count') AND ($session = 'all' OR otel_resource_attributes->>'session_id' = $session) AND ($build = '' OR otel_resource_attributes->>'build.id' = $build) GROUP BY time_bucket('5 seconds', recorded_timestamp), service_name, service_namespace, deployment_environment, service_instance_id, attributes 
) SELECT time, concat('Frames above 25 ms', ' · source ', CAST(dense_rank() OVER (ORDER BY service_name, service_namespace, deployment_environment, service_instance_id, CAST(attributes AS TEXT)) AS TEXT)) AS series, value FROM observations ORDER BY time DESC LIMIT 10000
